"""GCU400 specialization of ``aten::_cudnn_rnn_flatten_weight``.

The shared implementation gathers the copy plan (source address, destination
offset, length) into an int64 device descriptor and lets one kernel dereference
the addresses.  GCU has no int64 support: ``torch_gcu`` silently narrows a Long
tensor to Int when it is transferred to the device, so the 64-bit source
addresses were truncated and the kernel dereferenced garbage -- the very first
call died with a device ``Sip exception``.

This version therefore never puts a pointer value into a device buffer: the
copy plan stays on the host and every run is launched as its own contiguous
copy, with the source tensor passed as a real pointer argument.  A run that
must stay zero (cuDNN always reserves room for the biases) is filled on the
host-side plan instead of being masked out inside the kernel.

Everything else (plan construction, canonical-storage fast path, weight
rebinding, ``.out`` semantics) is unchanged from the shared implementation.
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

logger = logging.getLogger(__name__)

# cudnnRNNMode_t: RNN_RELU=0, RNN_TANH=1, LSTM=2, GRU=3
# The number of "gates" decides how many rows each linear layer matrix has.
_NUM_GATES = {
    0: 1,  # RNN_RELU
    1: 1,  # RNN_TANH
    2: 4,  # LSTM
    3: 3,  # GRU
}

# Weights can be of any 1/2/4-byte dtype; the copy is done bitwise by viewing the
# buffers through an integer type of the same width so the kernel does not need
# one specialization per dtype.  8-byte elements (float64) are rejected: GCU has
# no int64 datapath to copy them bitwise.
_ELEM_TO_TL_DTYPE = {
    1: tl.int8,
    2: tl.int16,
    4: tl.int32,
}

# Elements copied per program of a run.
BLOCK_SIZE = 2048


@triton.jit
def _segment_copy_kernel(
    src_ptr,
    out_ptr,
    dst_offset,
    n_elements,
    ELEM_DTYPE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Copy one contiguous run of one weight tensor into the flat buffer.

    ``src_ptr`` is a real pointer argument rather than an address loaded from a
    descriptor, because GCU cannot carry 64-bit pointer values through memory.
    """
    pid = tl.program_id(0)
    out = out_ptr.to(tl.pointer_type(ELEM_DTYPE))
    src = src_ptr.to(tl.pointer_type(ELEM_DTYPE))
    offsets = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offsets < n_elements
    tl.store(out + dst_offset + offsets, tl.load(src + offsets, mask=mask), mask=mask)


def _build_copy_plan(
    weight_arr,
    weight_stride0,
    input_size,
    mode,
    hidden_size,
    proj_size,
    num_layers,
    bidirectional,
):
    """Reproduce the cuDNN flat-weight layout as a list of copy runs.

    The flat buffer holds, for every (layer, direction) group, the input
    matrices followed by the recurrent matrices (and the projection matrix for
    projected LSTMs); all biases of all groups are appended at the very end.
    """
    if mode not in _NUM_GATES:
        raise RuntimeError(f"cudnn_rnn_flatten_weight: unsupported mode {mode}")
    if num_layers < 1:
        raise RuntimeError(
            f"cudnn_rnn_flatten_weight: num_layers must be >= 1, got {num_layers}"
        )

    gates = _NUM_GATES[mode]
    num_dirs = 2 if bidirectional else 1
    has_proj = proj_size > 0
    # Width of the recurrent matrices, which is also the input width of every
    # layer except the first one.
    hidden_out = proj_size if has_proj else hidden_size
    num_weights = 2 + (1 if has_proj else 0)
    has_bias = weight_stride0 - num_weights == 2
    if not has_bias and weight_stride0 != num_weights:
        raise RuntimeError(
            "cudnn_rnn_flatten_weight: weight_stride0 "
            f"({weight_stride0}) does not match a weights-only ({num_weights}) "
            f"or weights-and-biases ({num_weights + 2}) group"
        )

    num_groups = num_layers * num_dirs
    if len(weight_arr) < num_groups * weight_stride0:
        raise RuntimeError(
            "cudnn_rnn_flatten_weight: number of layers mismatch, got "
            f"{len(weight_arr)} tensors for {num_groups} layer groups of "
            f"{weight_stride0} tensors"
        )

    # With biases the projection matrix is the last element of a group,
    # without biases it directly follows the two weight matrices.
    proj_slot = 4 if has_bias else 2

    runs = []
    offset = 0
    for group in range(num_groups):
        layer = group // num_dirs
        in_size = input_size if layer == 0 else num_dirs * hidden_out
        sizes = [gates * hidden_size * in_size, gates * hidden_size * hidden_out]
        if has_proj:
            sizes.append(proj_size * hidden_size)
        for k, size in enumerate(sizes):
            src = group * weight_stride0 + (k if k < 2 else proj_slot)
            runs.append((src, offset, size))
            offset += size

    bias_size = gates * hidden_size
    for group in range(num_groups):
        for k in (2, 3):
            if has_bias:
                runs.append((group * weight_stride0 + k, offset, bias_size))
            else:
                runs.append((-1, offset, bias_size))
            offset += bias_size

    for src, _, size in runs:
        if src < 0:
            continue
        if weight_arr[src].numel() != size:
            raise RuntimeError(
                "cudnn_rnn_flatten_weight: weight "
                f"{src} has {weight_arr[src].numel()} elements but the cuDNN "
                f"flat layout expects {size}"
            )

    return runs, offset


def _canonical_base(weight_arr, runs, total):
    """Return the storage the weights already share, or None.

    ``nn.RNNBase.flatten_parameters()`` runs on every ``forward()``, so after
    the first flatten the weights are contiguous views into one flat buffer,
    each sitting exactly at the offset the copy plan assigns it.  In that state
    the flat buffer *is* the input storage, so there is nothing to copy and
    nothing to rebind.
    """
    base = None
    next_dst = 0
    for src, dst, size in runs:
        if size == 0:
            continue
        # The runs must tile the whole buffer in plan order; otherwise the
        # input storage is not the flat buffer.
        if dst != next_dst:
            return None
        next_dst += size
        if src < 0:
            # A reserved bias slot.  It must stay zero in the flat buffer, and
            # in a buffer produced by this operator it already is.
            continue
        w = weight_arr[src]
        storage = w.untyped_storage()
        if base is None:
            base = storage
        elif storage.data_ptr() != base.data_ptr():
            return None
        # An untyped-storage offset is measured in elements, the same unit as
        # the plan's ``dst``, so this is an exact host-side check.
        if w.storage_offset() != dst or w.numel() != size or not w.is_contiguous():
            return None
    if base is None or next_dst != total:
        return None
    return base


def _rebind_weights(weight_arr, runs, out, total):
    """Point every weight at its slot inside the flat ``out`` buffer.

    This mirrors the reference operator's ``set_orig_weights_to_flat_buf`` step
    (PyTorch ``cudnn/RNN.cpp``): after the call each ``weight_arr[i]`` is a view
    into the flat buffer instead of its original storage.
    """
    if total == 0:
        return
    out_storage = out.untyped_storage()
    # ``set_`` on a leaf that requires grad is an in-place op, so it must run
    # under no_grad; ``nn.RNNBase.flatten_parameters`` does the same around its
    # call into the reference operator.
    with torch.no_grad():
        for src, dst, size in runs:
            if src < 0 or size == 0:
                continue
            w = weight_arr[src]
            if w.is_contiguous():
                # The slot is contiguous by construction, so the weight's own
                # strides describe it exactly.
                w.set_(out_storage, dst, w.shape, w.stride())
            else:
                # Same layout as the reference's ``view_as``: reshape the flat
                # slot so a non-contiguous weight keeps its logical element
                # order.
                w.set_(out.narrow(0, dst, size).reshape(w.shape))


